#!/usr/bin/env python3
"""Draft reusable Guide Me scaffolds for audited, source-approved items only."""
import copy,hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];OUT=Path(__file__).resolve().parent

def sha(x):return hashlib.sha256(json.dumps(x,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()
def main():
 audit=json.loads((OUT/'numerical84-audit-v0.1.json').read_text())
 recipes=json.loads((OUT/'family-recipes-luna-v0.1.json').read_text())
 by_id={r['question_id']:r for r in audit['items']};state=json.loads(__import__('gzip').decompress((OUT/'bulk-state.json.gz').read_bytes()))
 template={
  'order-of-operations':{'purpose':'Test operation-priority understanding before revealing arithmetic.','prompt_parentheses':'Which rule tells you how to begin this expression?','prompt_no_parentheses':'Which rule tells you what to calculate before the final addition or subtraction?','choices':[{'id':'priority','text':'Handle parentheses first; then multiplication/division before addition/subtraction, working left to right among equal-priority operations.','role':'correct_rule','feedback':'Good: apply the same priority rule throughout the expression. This response checks the rule, not yet whether each calculation is accurate.'},{'id':'left-to-right','text':'Always calculate strictly from left to right, even when addition appears before multiplication.','role':'common-error','feedback':'Left-to-right applies only among operations at the same priority. Multiplication/division come before addition/subtraction.'},{'id':'add-first','text':'Add or subtract as soon as those signs appear, then multiply or divide.','role':'common-error','feedback':'Addition/subtraction do not take priority over multiplication/division. Check parentheses first, then the higher-priority operations.'},{'id':'unsure','text':'I am unsure, guessed, or used another approach.','role':'uncertain','feedback':'No cause is established yet. We can identify the first valid operation together.'}], 'confirmation':'Which step did you actually take first: the one you selected, another step, or did you misclick/guess? A selection alone is only a hypothesis.'},
  'constant-step':{'purpose':'Test whether the learner recognizes equal gaps without revealing the next term.','prompt':'What relationship do the consecutive terms follow?','choices':[{'id':'constant-gap','text':'The same amount is added each time.','role':'correct-rule','feedback':'Yes. Check each gap to verify it stays equal, then use that gap once more. This is a rule check, not proof of independent transfer.'},{'id':'growing-gap','text':'The amount added increases by the same amount each time.','role':'common-error','feedback':'Compare the actual gaps. If they are equal, do not make them grow.'},{'id':'constant-ratio','text':'Each term is multiplied by the same factor.','role':'common-error','feedback':'Check division between neighboring terms. Here the rule is additive, not a constant multiplier.'},{'id':'unsure','text':'I am unsure, guessed, or used another approach.','role':'uncertain','feedback':'No cause is established. Write each gap between neighboring terms and compare them.'}], 'confirmation':'Did you use that rule when you first answered, choose it after seeing the terms, or select it by mistake?'} ,
  'linear-gap-growth':{'purpose':'Test interpretation of changing differences, not the final arithmetic.','prompt':'How do the gaps between neighboring terms change?','choices':[{'id':'linear-gap-growth','text':'The gaps increase or decrease by the same amount each time.','role':'correct-rule','feedback':'Yes. Compare consecutive gaps, then extend the gap pattern one step. This checks pattern recognition, not independent transfer.'},{'id':'constant-gap','text':'The same amount is added each time.','role':'common-error','feedback':'The gaps themselves change. Write them out and compare the change from one gap to the next.'},{'id':'constant-ratio','text':'Each term is multiplied by a fixed number.','role':'common-error','feedback':'Test a multiplier between neighboring terms. The visible rule is in the differences.'},{'id':'unsure','text':'I am unsure, guessed, or used another approach.','role':'uncertain','feedback':'No cause is established. First list the differences; do not calculate the next term yet.'}], 'confirmation':'Did you actually use this gap rule, or did you choose it now/guess/misclick?'} ,
  'consecutive-squares':{'purpose':'Test recognition of square terms without revealing the next square.','prompt':'What familiar number relationship best describes the terms?','choices':[{'id':'consecutive-squares','text':'They are consecutive perfect squares.','role':'correct-rule','feedback':'Check each term against its square root. Then extend the root pattern by one. This response alone is not transfer evidence.'},{'id':'constant-gap','text':'They have a constant difference.','role':'common-error','feedback':'Write the gaps: they do not stay constant. Look at the terms themselves as squares.'},{'id':'linear-gap-growth','text':'The gaps grow by a fixed amount.','role':'common-error','feedback':'Compare the pattern of the terms as well as the gaps. Consecutive squares give a direct rule here.'},{'id':'unsure','text':'I am unsure, guessed, or used another approach.','role':'uncertain','feedback':'No cause is established. Check whether each term has a whole-number square root.'}], 'confirmation':'Was that the rule you used before answering, or is this a new recognition?'} ,
  'sum-previous-two':{'purpose':'Test the recurrence rule without revealing the next term.','prompt':'How is each new term formed?','choices':[{'id':'sum-previous-two','text':'Add the two immediately preceding terms.','role':'correct-rule','feedback':'Check that this works for every term after the first two. Then apply it once to continue. This response alone is not transfer evidence.'},{'id':'constant-gap','text':'Add the same fixed amount each time.','role':'common-error','feedback':'Compare the gaps; they change. Test the relationship between two preceding terms instead.'},{'id':'constant-ratio','text':'Multiply each term by the same number.','role':'common-error','feedback':'Check whether one fixed multiplier works throughout. Here the recurrence uses a sum.'},{'id':'unsure','text':'I am unsure, guessed, or used another approach.','role':'uncertain','feedback':'No cause is established. Compare each term with the two immediately before it.'}], 'confirmation':'Did you use this rule in your original attempt, or did you choose it after seeing these choices?'} ,
  'consecutive-primes':{'purpose':'Test recognition of prime terms without revealing the next prime.','prompt':'What property do the listed terms share?','choices':[{'id':'consecutive-primes','text':'They are consecutive prime numbers.','role':'correct-rule','feedback':'Check that each term has no positive divisors other than 1 and itself, and that no prime is skipped. Then find the next one.'},{'id':'constant-gap','text':'They have a fixed gap.','role':'common-error','feedback':'The gaps change. Check the number property shared by all terms.'},{'id':'linear-gap-growth','text':'Their gaps grow by a fixed amount.','role':'common-error','feedback':'That can be another possible rule for some finite lists. Check which rule the supplied choices and explanation support.'},{'id':'unsure','text':'I am unsure, guessed, or used another approach.','role':'uncertain','feedback':'No cause is established. Test divisibility and check whether any prime is skipped.'}], 'confirmation':'Was this the rule behind your original answer, or did you infer it just now?'} ,
  'square-number-differences':{'purpose':'Test the gap pattern without revealing its next value.','prompt':'What pattern do the successive gaps follow?','choices':[{'id':'square-gaps','text':'The gaps are consecutive square numbers.','role':'correct-rule','feedback':'Check each gap against 1², 2², 3², and so on. Then extend the gap pattern once.'},{'id':'constant-gap','text':'The same amount is added each time.','role':'common-error','feedback':'The gaps are not equal. Compare the gaps with square numbers.'},{'id':'linear-gap-growth','text':'The gaps increase by the same fixed amount.','role':'common-error','feedback':'Check the actual gap sizes; their values follow squares rather than a constant increase.'},{'id':'unsure','text':'I am unsure, guessed, or used another approach.','role':'uncertain','feedback':'No cause is established. List the gaps, then test whether each is a square.'}], 'confirmation':'Did you use the square-gap rule before answering, or is this a new insight?'} }
 bindings=[];source_cache={};
 for a in audit['items']:
  row=next(x for x in state['records'] if x['question_id']==a['question_id'])
  if row['bank_status']!='approved':continue
  qfile=ROOT/row['source_file']
  if str(qfile) not in source_cache:source_cache[str(qfile)]={q['id']:q for q in json.loads(qfile.read_text())['items']}
  q=source_cache[str(qfile)][a['question_id']]
  assert sha(q)==a['source_hash']
  pattern=a.get('concept_family')
  if a['archetype']=='NUM-OPS-ORDER':tid='order-of-operations'
  else:
   mapfam={'arithmetic-sequence':'constant-step','arithmetic-first-differences':'linear-gap-growth','consecutive-squares':'consecutive-squares','sum-previous-two':'sum-previous-two','consecutive-primes':'consecutive-primes','square-number-differences':'square-number-differences'}
   tid=mapfam.get(pattern)
  if not tid:continue
  t=copy.deepcopy(template[tid])
  if tid=='order-of-operations':t['prompt']=t['prompt_parentheses'] if '(' in q['stem'] else t['prompt_no_parentheses']
  nums=a.get('sequence')
  bindings.append({'question_id':q['id'],'source_file':row['source_file'],'source_record_sha256':a['source_hash'],'bank_status_at_authoring':'approved','difficulty':q.get('difficulty'),'language':q.get('language'),'concept_family':pattern,'diagnostic_template':tid,'diagnostic':t,'verified_answer':{'option_id':q['answer_option_id'],'value':a['exact_answer'],'method':'restricted exact-rational evaluation' if a['archetype']=='NUM-OPS-ORDER' else 'recognized conventional pattern; single offered option agrees with stored key','checks':['answer matches stored key','one offered answer per supported rule','canonical explanation and all distractor codes present']},'solution_reference':{'explanation':q['reveal']['why_correct'],'hint':q['reveal'].get('shortcut',q['reveal'].get('terms')),'source_record_sha256':a['source_hash']},'transfer':{'approved_question_id':None,'reason':'No distinct-family transfer has been verified in this 84-item batch.'},'outcome_contract':{'diagnostic_is_assisted':True,'hypothesis_status':'candidate_only_until_confirmation_and_repeated_evidence','uncertain_or_misclick_assigns_hypothesis':False,'correct_diagnostic_is_not_mastery':True,'later_retry_is_assisted':True},'status':'draft','editorial_review':None,'runtime_eligible':False})
 data={'schema_version':'dexter-numerical84-guide-draft-v0.1','baseline_commit':'8b69fffbba83fc663e6a2389bdae880a325314d8','status':'draft','runtime_eligible':False,'independent_review':None,'learner_evidence':None,'templates':template,'bindings':bindings,'excluded_nonapproved_ids':[a['question_id'] for a in audit['items'] if a['bank_status']!='approved'],'notes':['These are draft Study Mode scaffolds, not runtime-ready tutoring.','The initial diagnostic tests the named rule before solution reveal; self-report confirmation and repeated evidence are required before a misconception hypothesis is retained.','Canonical stems, keys, options, status and source fields were not changed.','No approved distinct-family transfer is asserted.']}
 p=OUT/'numerical84-guide-draft-v0.1.json';p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n');print('approved-source bindings',len(bindings),'excluded',len(data['excluded_nonapproved_ids']),'families',sorted(set(x['diagnostic_template'] for x in bindings)))
if __name__=='__main__':main()
